cat > src/claim-office.spec.ts <<'EOF'
import { describe, it } from "vitest";

describe("MHPCO Claim Office", () => {
  // --- Premium: simplest cases -------------------------------------------
  it.todo("quotes an empty item list as 5 G (processing fee only)");
  it.todo("quotes a single plain sword as 105 G (100 G base + 5 G fee)");
  it.todo("quotes a single plain amulet as 65 G (60 G base + 5 G fee)");
  it.todo("quotes a single plain staff as 85 G (80 G base + 5 G fee)");
  it.todo("quotes a single plain potion as 45 G (40 G base + 5 G fee)");
  it.todo("quotes a single rune as 30 G (25 G base + 5 G fee)");
  it.todo("quotes a single moonstone as 30 G (25 G base + 5 G fee)");
  it.todo("quotes a plain sword and a plain amulet as 165 G (100 + 60 base + 5 G fee)");

  // --- Component building blocks -----------------------------------------
  it.todo("quotes 2 runes at base premium 50 G (no block)");
  it.todo("quotes 3 runes at base premium 60 G (block applies)");
  it.todo("quotes 4 runes at base premium 100 G (no block -- block requires exactly 3)");
  it.todo("quotes 7 runes at base premium 175 G (no block)");
  it.todo("quotes 2 runes + 1 moonstone at base premium 75 G (no block: alike means same type)");
  it.todo("quotes 3 runes + 3 moonstones at base premium 120 G (two separate blocks)");

  // --- Item-specific modifiers -------------------------------------------
  it.todo("adds a 50 % curse surcharge to a cursed item's base premium -- cursed sword 150 G base + fee = 155 G");
  it.todo("adds a 30 % high-enchantment surcharge at enchantment exactly 5 -- sword 130 G base + fee = 135 G");
  it.todo("adds no high-enchantment surcharge at enchantment 4 -- sword 100 G base + fee = 105 G");
  it.todo("applies both curse and high-enchantment surcharges to a cursed sword with enchantment 5 -- 180 G + fee = 185 G");
  it.todo("applies item-specific surcharges only to the affected item -- cursed sword + plain amulet = 210 G before fee, 215 G total");

  // --- Policy-wide modifiers ---------------------------------------------
  it.todo("applies the 20 % loyalty discount at exactly 2 years with MHPCO -- sword 100 - 20 + 10 first insurance + 5 fee = 95 G");
  it.todo("applies no loyalty discount at 1 year with MHPCO -- sword 100 + 10 first insurance + 5 fee = 115 G");
  it.todo("applies the 10 % first-insurance surcharge on the first quote -- sword 100 + 10 + 5 = 115 G");
  it.todo("applies the 15 % follow-up discount to the customer's second quote -- second sword quote 100 + 10 - 15 + 5 = 100 G");
  it.todo("applies the first-insurance surcharge again on a follow-up contract (each quoted item is a first insurance)");

  // --- Rounding ----------------------------------------------------------
  it.todo("rounds a premium of 197.5 G up to 198 G (MHPCO's favor)");
  it.todo("keeps intermediate amounts fractional and rounds only the final premium");

  // --- Integration examples ----------------------------------------------
  it.todo("quotes the newcomer's cursed sword (0 years, steel, ench 3) as 165 G");
  it.todo("quotes the long-standing customer's second contract (3 years, cursed sword ench 7) as 160 G");

  // --- Quote errors ------------------------------------------------------
  it.todo("rejects a quote containing an unknown item type (e.g. broomstick) -- throws an Error; CLI exits non-zero with stderr message and no stdout results");

  // --- Insurance sum and cap ---------------------------------------------
  it.todo("derives insurance sum 1600 G and cap 3200 G for a policy covering a sword and an amulet");
  it.todo("derives insurance sum 2000 G and cap 4000 G for a policy covering two swords");
  it.todo("derives insurance sum 1750 G and cap 3500 G for a sword + 3 runes (block affects premium only)");
  it.todo("bases the cap on the unmodified insurance value -- cursed sword (premium 165 G) still has cap 2000 G");

  // --- Claim: standard reimbursement -------------------------------------
  it.todo("pays 400 G for a steel sword (ench 3) with 500 G damage -- full reimbursement minus 100 G deductible");
  it.todo("pays 100 G for a damaged rune (200 G damage) -- runes have no enchantment or material");
  it.todo("reports the remaining cap after a claim -- sword policy cap 2000 G, payout 400 G, remainingCap 1600 G");

  // --- Claim: special clauses --------------------------------------------
  it.todo("reimburses 50 % for damage to an item with enchantment exactly 8 -- dragon sword, 1000 G damage, payout 400 G");
  it.todo("fully reimburses damage to a dragon-material item -- dragon sword ench 5, 800 G damage, payout 700 G");
  it.todo("applies the 50 % rule when both clauses apply -- dragon sword ench 9, 1000 G damage, payout 400 G");
  it.todo("applies only the high-enchantment clause to a steel sword ench 9 -- 1000 G damage, payout 400 G");

  // --- Claim: deductible per damage event --------------------------------
  it.todo("applies the 100 G deductible once per damaged item -- sword 500 G + amulet 300 G damage, payout 600 G");
  it.todo("treats two damage entries of the same item type as separate damages with their own deductibles");
  it.todo("floors a negative per-damage reimbursement at 0 G rather than deducting from other damages");

  // --- Claim: cap exhaustion ---------------------------------------------
  it.todo("pays 1400 G and leaves 600 G cap for the first 1500 G claim on a sword policy (cap 2000 G)");
  it.todo("reduces the second 1500 G claim to the remaining cap -- payout 600 G, remainingCap 0 G");

  // --- Claim: rounding ---------------------------------------------------
  it.todo("rounds a payout of 350.5 G down to 350 G (MHPCO's favor)");

  // --- Claim errors ------------------------------------------------------
  it.todo("rejects a claim whose damaged item is not part of the policy (amulet damaged, only sword insured) -- throws an Error; CLI exits non-zero");
  it.todo("rejects a claim referencing an unknown item type -- throws an Error; CLI exits non-zero");
  it.todo("rejects a claim with more damage entries of a type than the policy covers (two sword damages, one sword insured) -- throws an Error; CLI exits non-zero");
  it.todo("rejects a claim with a negative damage amount (-200) -- throws an Error; CLI exits non-zero");

  // --- CLI ---------------------------------------------------------------
  it.todo("CLI reads a scenario from stdin and writes {results:[...]} to stdout in step order");
  it.todo("CLI processes the schema example -- amulet quote then 200 G amulet claim");
  it.todo("CLI resolves a claim's policy field to the zero-based index of the quote step");
  it.todo("CLI exits non-zero and writes to stderr without stdout results on an invalid scenario");
});
EOF
