import { claim, type Incident } from "./claim.js";
import type { Customer, Item } from "./item.js";
import { payoutCap } from "./policy.js";
import { quote } from "./quote.js";

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: Incident;
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export type StepResult =
  | { premium: number }
  | { payout: number; remainingCap: number };

interface Policy {
  items: Item[];
  remainingCap: number;
}

function policyAt(policies: Map<number, Policy>, index: number): Policy {
  const policy = policies.get(index);
  if (policy === undefined) {
    throw new Error(`Claim refers to step ${index}, which created no policy`);
  }
  return policy;
}

export function runScenario(scenario: Scenario): StepResult[] {
  const policies = new Map<number, Policy>();
  return scenario.steps.map((step, index) => {
    if (step.op === "quote") {
      const premium = quote(scenario.customer, step.items, policies.size);
      policies.set(index, {
        items: step.items,
        remainingCap: payoutCap(step.items),
      });
      return { premium };
    }
    const policy = policyAt(policies, step.policy);
    const result = claim(policy.items, step.incident, policy.remainingCap);
    policy.remainingCap = result.remainingCap;
    return result;
  });
}
EOF
